from boltons.urlutils import URL

def test_chain_navigate():
    try:
        url = URL('http://example.com/a/b').navigate('c').navigate('d')
        print("Success!")
        print(f"Result: {url}")
    except TypeError as e:
        print(f"Caught expected TypeError: {e}")
        raise e

if __name__ == "__main__":
    test_chain_navigate()
